<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor\TenantLoginProviderSamlIdpSsoUrlAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderSamlIdpSsoUrlAccessor trait.
 *
 * Covers null default, string/VO assignment via withSamlIdpSsoUrl,
 * getSamlIdpSsoUrl/samlIdpSsoUrl accessors, and isSamlIdpSsoUrlChanged with/without original.
 */
class TenantLoginProviderSamlIdpSsoUrlAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSamlIdpSsoUrl creates a new instance with the SamlIdpSsoUrl set
     * from a string value, and getSamlIdpSsoUrl returns the primitive string.
     */
    public function testWithSamlIdpSsoUrlFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSamlIdpSsoUrlAccessorUnitTest();

        // Act
        $result = $holder->withSamlIdpSsoUrl('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getSamlIdpSsoUrl());
    }
    /**
     * Asserts that withsamlIdpSsoUrl has access to the value object
     * from a string value, and getSamlIdpSsoUrl returns the primitive string.
     */
    public function testWithSamlIdpSsoUrlFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSamlIdpSsoUrlAccessorUnitTest();

        // Act
        $result = $holder->withSamlIdpSsoUrl('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->samlIdpSsoUrl()->value());
    }
    public function testChangedSamlIdpSsoUrl(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSamlIdpSsoUrlAccessorUnitTest();
        $original = $holder->withSamlIdpSsoUrl('one');
        $same = $holder->withSamlIdpSsoUrl('one');
        $modified = $holder->withSamlIdpSsoUrl('other');

        // Act
        $unchanged = $holder->isSamlIdpSsoUrlChanged();
        $withSame = $original->isSamlIdpSsoUrlChanged($same);
        $withDiferent = $original->isSamlIdpSsoUrlChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantLoginProviderSamlIdpSsoUrlAccessorUnitTest
{
    use TenantLoginProviderSamlIdpSsoUrlAccessor;
}
